DROP TABLE IF EXISTS "public"."follow" CASCADE;
DROP TABLE IF EXISTS "public"."comment" CASCADE;
DROP TABLE IF EXISTS "public"."like" CASCADE;
DROP TABLE IF EXISTS "public"."post" CASCADE;
CREATE TABLE IF NOT EXISTS "public"."club" ("id" text NOT NULL, "address" text NOT NULL DEFAULT '', "average_rating" double precision NOT NULL DEFAULT 0, "category" text NOT NULL DEFAULT '', "city" text NOT NULL DEFAULT '', "contact_email" text, "current_capacity_percent" integer NOT NULL DEFAULT 0, "external_search_tags" text NOT NULL DEFAULT '', "female_percentage" integer NOT NULL DEFAULT 0, "geofence_radius_meters" double precision NOT NULL DEFAULT 200, "image_url" text NOT NULL DEFAULT '', "instagram_handle" text, "is_favorite" boolean NOT NULL DEFAULT false, "is_promoted" boolean NOT NULL DEFAULT false, "latitude" double precision NOT NULL DEFAULT 0, "longitude" double precision NOT NULL DEFAULT 0, "male_percentage" integer NOT NULL DEFAULT 0, "name" text NOT NULL, "opening_hours_json" text NOT NULL DEFAULT '', "phone_number" text, "postal_code" text NOT NULL DEFAULT '', "rating" double precision NOT NULL DEFAULT 0, "region" text NOT NULL DEFAULT '', "total_live_visitors" integer NOT NULL DEFAULT 0, "website_url" text, PRIMARY KEY ("id"));
ALTER TABLE "public"."user" ALTER COLUMN "id" TYPE text, ALTER COLUMN "created_at" DROP NOT NULL, ALTER COLUMN "first_name" DROP NOT NULL, ALTER COLUMN "last_name" DROP NOT NULL, ADD COLUMN IF NOT EXISTS "age" integer, ADD COLUMN IF NOT EXISTS "gender" text NOT NULL DEFAULT 'UNSPECIFIED', ADD COLUMN IF NOT EXISTS "hometown" text, ADD COLUMN IF NOT EXISTS "is_verified" boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS "profile_picture_url" text, ADD COLUMN IF NOT EXISTS "updated_at" timestamptz;
CREATE TABLE IF NOT EXISTS "public"."event" ("id" text NOT NULL, "club_id" text NOT NULL, "capacity_limit" integer NOT NULL DEFAULT 0, "category" text NOT NULL DEFAULT '', "description" text NOT NULL, "end_time" bigint NOT NULL DEFAULT 0, "image_url" text, "is_cancelled" boolean NOT NULL DEFAULT false, "price" text NOT NULL DEFAULT '', "search_keywords" text NOT NULL DEFAULT '', "special_offers_json" text NOT NULL DEFAULT '', "start_time" bigint NOT NULL DEFAULT 0, "time" text NOT NULL DEFAULT '', "title" text NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "event_club_id_fkey" FOREIGN KEY ("club_id") REFERENCES "public"."club" ("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "public"."club_offer" ("id" text NOT NULL, "club_id" text NOT NULL, "description" text NOT NULL, "discount_code" text, "discount_percentage" integer, "image_url" text, "is_exclusive" boolean NOT NULL DEFAULT false, "offer_type" text NOT NULL, "terms_and_conditions" text, "title" text NOT NULL, "valid_until" bigint, PRIMARY KEY ("id"), CONSTRAINT "club_offer_club_id_fkey" FOREIGN KEY ("club_id") REFERENCES "public"."club" ("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "public"."review" ("id" text NOT NULL, "club_id" text, "event_id" text, "reviewer_user_id" text NOT NULL, "flagged_count" integer NOT NULL DEFAULT 0, "helpful_votes_count" integer NOT NULL DEFAULT 0, "is_verified" boolean NOT NULL DEFAULT false, "rating" integer NOT NULL, "reviewer_avatar_url" text, "reviewer_username" text NOT NULL DEFAULT '', "target_user_id" text, "text" text NOT NULL, "timestamp" bigint NOT NULL, "verification_method" text NOT NULL DEFAULT 'UNVERIFIED', PRIMARY KEY ("id"), CONSTRAINT "review_club_id_fkey" FOREIGN KEY ("club_id") REFERENCES "public"."club" ("id") ON DELETE SET NULL, CONSTRAINT "review_event_id_fkey" FOREIGN KEY ("event_id") REFERENCES "public"."event" ("id") ON DELETE SET NULL, CONSTRAINT "review_reviewer_user_id_fkey" FOREIGN KEY ("reviewer_user_id") REFERENCES "public"."user" ("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "public"."chat" ("id" text NOT NULL, "avatar_initial" text NOT NULL, "avatar_url" text, "chat_type" text NOT NULL, "city_region" text, "is_archived" boolean NOT NULL DEFAULT false, "is_muted" boolean NOT NULL DEFAULT false, "is_online" boolean NOT NULL DEFAULT false, "is_pinned" boolean NOT NULL DEFAULT false, "last_message_text" text NOT NULL, "last_message_timestamp_iso" text NOT NULL DEFAULT '', "last_message_timestamp_ms" bigint NOT NULL, "last_read_message_id" text, "name" text NOT NULL, "unread_count" integer NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "public"."message" ("id" text NOT NULL, "chat_id" text NOT NULL, "aspect_ratio" double precision NOT NULL DEFAULT 1, "audio_duration_ms" bigint NOT NULL DEFAULT 0, "caption" text, "delivered_at_ms" bigint, "is_edited" boolean NOT NULL DEFAULT false, "is_mine" boolean NOT NULL, "media_height" integer NOT NULL DEFAULT 0, "media_url" text, "media_width" integer NOT NULL DEFAULT 0, "message_type" text NOT NULL DEFAULT 'TEXT', "read_at_ms" bigint, "reply_to_message_id" text, "sender_name" text NOT NULL, "sender_user_id" text NOT NULL DEFAULT '', "status" text NOT NULL DEFAULT 'SENT', "text" text NOT NULL, "thumbnail_url" text, "timestamp_iso" text NOT NULL DEFAULT '', "timestamp_ms" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "message_chat_id_fkey" FOREIGN KEY ("chat_id") REFERENCES "public"."chat" ("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "public"."direct_message" ("id" text NOT NULL, "receiver_id" text NOT NULL, "sender_id" text NOT NULL, "aspect_ratio" double precision NOT NULL DEFAULT 1, "audio_duration_ms" bigint NOT NULL DEFAULT 0, "caption" text, "delivered_at_ms" bigint, "delivery_status" text NOT NULL DEFAULT 'SENT', "encryption_algorithm" text NOT NULL DEFAULT 'AES-256-GCM', "is_encrypted" boolean NOT NULL DEFAULT true, "media_height" integer NOT NULL DEFAULT 0, "media_url" text, "media_width" integer NOT NULL DEFAULT 0, "message_type" text NOT NULL DEFAULT 'TEXT', "read_at_ms" bigint, "text" text NOT NULL, "thumbnail_url" text, "timestamp" bigint NOT NULL, "timestamp_iso" text NOT NULL DEFAULT '', PRIMARY KEY ("id"), CONSTRAINT "direct_message_receiver_id_fkey" FOREIGN KEY ("receiver_id") REFERENCES "public"."user" ("id") ON DELETE CASCADE, CONSTRAINT "direct_message_sender_id_fkey" FOREIGN KEY ("sender_id") REFERENCES "public"."user" ("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "public"."friend" ("user_id" text NOT NULL, "friend_user_id" text NOT NULL, "created_at_timestamp_ms" bigint NOT NULL, "is_qr_verified" boolean NOT NULL DEFAULT true, "status" text NOT NULL DEFAULT 'ACCEPTED', PRIMARY KEY ("user_id", "friend_user_id"));
CREATE TABLE IF NOT EXISTS "public"."visited_log" ("id" text NOT NULL, "club_id" text NOT NULL, "user_id" text NOT NULL, "club_name" text NOT NULL, "is_verified_by_gps" boolean NOT NULL, "visited_at_timestamp" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "visited_log_club_id_fkey" FOREIGN KEY ("club_id") REFERENCES "public"."club" ("id") ON DELETE CASCADE, CONSTRAINT "visited_log_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "public"."user" ("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "public"."blocked_user" ("user_id" text NOT NULL, "blocked_user_id" text NOT NULL, "blocked_at_timestamp_ms" bigint NOT NULL, "reason" text, PRIMARY KEY ("user_id", "blocked_user_id"));
CREATE TABLE IF NOT EXISTS "public"."user_preference" ("user_id" text NOT NULL, "drinking_habit" text NOT NULL DEFAULT 'NEVER', "is_dark_mode" boolean NOT NULL DEFAULT false, "push_notifications_enabled" boolean NOT NULL DEFAULT true, "search_intent" text NOT NULL DEFAULT 'BOTH', "search_radius_km" integer NOT NULL DEFAULT 10, "smoking_habit" text NOT NULL DEFAULT 'NEVER', PRIMARY KEY ("user_id"), CONSTRAINT "user_preference_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "public"."user" ("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "public"."user_location" ("id" text NOT NULL DEFAULT gen_random_uuid()::text, "accuracy" double precision NOT NULL, "latitude" double precision NOT NULL, "longitude" double precision NOT NULL, "speed" double precision NOT NULL DEFAULT 0, "timestamp_ms" bigint NOT NULL, PRIMARY KEY ("id"));
